most_likes = like.PARTITION(name='student_likes', by=liked_id).CALCULATE(
    num_likes=COUNT(like)
).TOP_K(1, by=num_likes.DESC()).highschooler.CALCULATE(student_name=name)

top_companies = gas_company.companies.TOP_K(3, by=assets_billion.DESC())

stations_of_top_companies = gas_company.station_companies.WHERE(
    HAS(company) == 1
).WHERE(
    ISIN(company_id, top_companies.CALCULATE(company_id=company_id))
)

final_result = gas_company.gas_stations.WHERE(
    HAS(station_companies) == 1
).WHERE(
    ISIN(station_id, stations_of_top_companies.CALCULATE(station_id=station_id))
).CALCULATE(
    location=location,
    representative_name=representative_name
)

most_popular_course = Student_Enrolment_Courses.PARTITION(
    name="course_groups", by=course_id
).CALCULATE(
    num_students=COUNT(Student_Enrolment_Courses),
    course_id_calc = course_id
).TOP_K(1, by=num_students.DESC()).CALCULATE(course_name=course.course_name)

tv_lounge_students = dorm_1.dorm_amenities.WHERE(
    amenity_name == "TV Lounge"
).has_amenities.dorm.lives_ins.student.CALCULATE(
    fname=fname,
    age=age
)

most_used_service_type = service.CALCULATE(
    service_type_code=service_type_code
).PARTITION(name="service_types", by=service_type_code).CALCULATE(
    service_type_code=service_type_code,
    count=COUNT(service)
).ORDER_BY(count.DESC()).TOP_K(1, by=count.DESC()).service_types.CALCULATE(
    service_type_code=service_type_code
)

result = ref_service_type.WHERE(
    ref_service_type.service_type_code == most_used_service_type.SINGULAR().service_type_code
).CALCULATE(
    service_type_code=service_type_code,
    service_type_description=service_type_description
)

least_flights = flight.airline.CALCULATE(
    num_flights = COUNT(flight)
).TOP_K(1, by=num_flights.ASC()).CALCULATE(abbreviation=abbreviation, country=country)

most_liked_highschooler = highschoolers.CALCULATE(
    num_likes=COUNT(like)
).TOP_K(1, by=num_likes.DESC()).CALCULATE(name=name)

min_claim_customer = insurance_and_eClaims.claim_header.CALCULATE(
    min_amount=MIN(amount_claimed)
).claim_header.WHERE(amount_claimed == min_amount).policy.customer.CALCULATE(
    customer_details=customer_details
)

most_winning_aircraft = Aircraft.CALCULATE(
    num_matches=COUNT(matches)
).TOP_K(1, by=num_matches.DESC()).CALCULATE(aircraft_name=aircraft)

most_popular_semester = student_enrolments.PARTITION(name="semester_group", by=semester_id).CALCULATE(
    num_students=COUNT(student_enrolments)
).TOP_K(1, by=num_students.DESC()).semester.CALCULATE(semester_name=semester_name, semester_id=semester_id)

city_with_most_stores = store_product.store_districts.CALCULATE(
    district_id=district_id
).PARTITION(name="districts", by=district_id).CALCULATE(
    city_name=store_product.store_districts.district.headquartered_city,
    num_stores=COUNT(store_product.store_districts)
).TOP_K(1, by=num_stores.DESC())

math_advisors = college_2.students.WHERE(dept_name == "Math").advisors.instructor.CALCULATE(
    instructor_name=name, student_credits=student.tot_cred
).ORDER_BY(student_credits.ASC())

distinct_keyboard_customers = department_store.customer.WHERE(
    HAS(customer_order.order_item.product.WHERE(product_name == 'keyboard')) == 1
).CALCULATE(distinct_customer_names=NDISTINCT(customer_name))

recent_contract = maintenance_contract.CALCULATE(
    recent_date=MAX(maintenance_contract.contract_end_date)
).SINGULAR().recent_date
most_recent_company_type = maintenance_contract.WHERE(
    contract_end_date == recent_contract
).third_party_company.CALCULATE(company_type=company_type)

most_recent_customer = insurance_and_eClaims.policy.CALCULATE(
